/** GENERATED by tools/pages (npm run build-pages) — the page catalogue. */
import type { Level, Page } from '../types';
import { LEVEL1 } from './level1';
import { LEVEL2 } from './level2';
import { LEVEL3 } from './level3';
import { LEVEL4 } from './level4';

export const PAGES: Page[] = [...LEVEL1, ...LEVEL2, ...LEVEL3, ...LEVEL4];

export const pagesOfLevel = (level: Level): Page[] => PAGES.filter((p) => p.level === level);
export const getPage = (id: string): Page | undefined => PAGES.find((p) => p.id === id);
